WITH x6 AS (SELECT MBRDISJOINT(x5.v60017, x5.v60017) AS x12, CAST(x5.v60019 AS UNSIGNED) AS x13, x5.v60017 FROM x15 GROUP BY x5.v60018) SELECT TIME('20:20:20') + INTERVAL '0.4' SECOND, CAST('1.2' AS YEAR) + 1.5e0, 1 - x5.v60018 AS x0, x5.v60019 + BIT_OR(x5.v60018) FROM v60015 AS x5 WHERE x5.v60018 = x5.v60016 AND x5.v60016 = 's%'